159: // Exposed contracts live in the project, so they import dependency files through the project's own aliases rather
160: // than the raw input source names (`npm/<name>@<version>/<path>`, `project/lib/<path>`, ...). Hardhat records those
161: // aliases as `[<context>:]<prefix>=<target>` remappings we invert here.
162: //
163: // Skip remappings whose target overlaps a project source: those alias the contracts being exposed rather than their
164: // dependencies, so inverting them would move the whole exposed tree under the alias.
165: function parseApplicableRemappings(remappings: string[], projectSourcePrefixes: string[]): ParsedRemapping[] {
166:   return remappings
167:     .flatMap(remapping => {
168:       const groups = remappingRegex.exec(remapping)?.groups as
169:         | { context: string | undefined; prefix: string; target: string }
170:         | undefined;
171:       return groups ? [groups] : [];
172:     })
173:     .filter(
174:       ({ context, target }) =>
175:         [undefined, '', 'project/'].includes(context) &&
176:         !projectSourcePrefixes.some(source => source.startsWith(target) || target.startsWith(source)),
177:     )
178:     .sort((a, b) => b.target.length - a.target.length) // Longest target first: most specific remapping wins.
179:     .map(({ prefix, target }) => ({ prefix, target }));
180: }
